package org.slavicmyths.verify;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.gametest.*;
import org.slavicmyths.poloz.*;
@GameTestHolder("slavicmyths_poloz") @PrefixGameTestTemplate(false)
public final class PolozRitualTests {
 @GameTest(template="empty",timeoutTicks=40) public static void simultaneousCommits(GameTestHelper t){var w=t.getLevel();var a=MorExposureTests.player(t);var b=MorExposureTests.player(t);var altar=a.blockPosition();var sample=net.minecraft.util.RandomSource.create(1832);double angle=sample.nextDouble()*Math.PI*2,radius=200+sample.nextDouble()*100;var spawn=altar.offset((int)(Math.cos(angle)*radius),0,(int)(Math.sin(angle)*radius));for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)w.getChunk((spawn.getX()>>4)+x,(spawn.getZ()>>4)+z);w.random.setSeed(1832);var first=new ItemStack(PolozContent.HORN.get());var second=new ItemStack(PolozContent.HORN.get());MorHorn.mark(first,true,null);MorHorn.mark(second,true,null);a.getInventory().setItem(0,new ItemStack(PolozContent.DUST.get(),4));b.getInventory().setItem(0,new ItemStack(PolozContent.DUST.get(),4));var d=PolozEvent.get(w);t.assertTrue(!d.running(),"isolated ritual fixture");d.cooldownUntil=w.getGameTime()+1;t.assertTrue(!d.commit(a,first,altar)&&MorHorn.dust(a)==4,"cooldown preserves cost");d.state=PolozEvent.State.IDLE;d.cooldownUntil=0;try{t.assertTrue(d.commit(a,first,altar),"first confirmed commit");t.assertTrue(!d.commit(b,second,altar),"second simultaneous request rejected");t.assertTrue(MorHorn.dust(a)==0&&MorHorn.dust(b)==4,"exact atomic cost");double distance=Math.hypot(d.spawn.getX()-altar.getX(),d.spawn.getZ()-altar.getZ());t.assertTrue(distance>=199&&distance<=301,"actual spawn ring "+distance);t.assertTrue(first.getCount()==1&&second.getCount()==1,"horn not consumed");}finally{d.finish(w,false);d.state=PolozEvent.State.IDLE;d.boss=null;d.cooldownUntil=0;d.setDirty();a.discard();b.discard();}t.succeed();}
 @GameTest(template="empty",timeoutTicks=40) public static void atomicFailure(GameTestHelper t){var w=t.getLevel();var p=MorExposureTests.player(t);p.getInventory().setItem(0,new ItemStack(PolozContent.DUST.get(),4));var horn=new ItemStack(PolozContent.HORN.get());MorHorn.mark(horn,true,null);var d=PolozEvent.get(w);var border=w.getWorldBorder();double oldSize=border.getSize(),oldX=border.getCenterX(),oldZ=border.getCenterZ();try{border.setCenter(p.getX(),p.getZ());border.setSize(2);t.assertTrue(!d.commit(p,horn,p.blockPosition()),"failed spawn reservation");t.assertTrue(MorHorn.dust(p)==4&&MorHorn.used(horn)&&horn.getCount()==1,"failure has no cost or flag loss");}finally{border.setCenter(oldX,oldZ);border.setSize(oldSize);p.discard();}t.succeed();}
 @GameTest(template="empty",timeoutTicks=160) public static void waterToShore(GameTestHelper t){var b=PolozGameTests.boss(t);var w=t.getLevel();var origin=b.blockPosition();for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++)for(int y=-2;y<0;y++)w.setBlockAndUpdate(origin.offset(x,y,z),Blocks.WATER.defaultBlockState());b.initializeBody();t.runAtTickTime(110,()->{t.assertTrue(b.isAlive()&&b.getAirSupply()>0,"water does not drown boss");t.assertTrue(!w.getFluidState(b.blockPosition().below()).is(net.minecraft.tags.FluidTags.WATER),"real shore exit");t.assertTrue(w.getFluidState(origin.below()).is(net.minecraft.tags.FluidTags.WATER),"water is not converted or destroyed");b.discard();t.succeed();});}
}
